INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Storm Rider 2', 'Storm Rider 2 is a new motion-based motorbike racing game for arcades and FEC’s so, riders start your engines! The impressive two player cabinet with futuristic bikes and impressive fully lit billboard captures players attention at any location. The motion delivers an unprecedented immersive racing experience. Combined with stunning graphics produced by the Unreal Engine and Boost function players will experience blazing fast speeds.' FROM games WHERE igdb_id = 240536 ON CONFLICT (game_id, language_code) DO NOTHING;
