INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truth of Beauty Witch: Marine''s Treasure Ship', 'A miraculous collaboration between Houshou Marine and "Tsugunohi" has come to fruition! When the main character becomes a crew member of a pirate ship led by Houshou Marine and realizes a certain fact, you are struck by a series of horrors. Can you unravel the secret behind Houshou Marine''s beauty?' FROM games WHERE igdb_id = 260291 ON CONFLICT (game_id, language_code) DO NOTHING;
