INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unaccomplished', 'Unaccomplished is a Yume Nikki fangame. Yin Ming wakes up on his balcony in the midst of a thunderstorm. He is unable to leave his room due to it, so all he has left to do is sleep, and dream. The player explores the dream world and collects effects that change Yin Ming''s form and grants him new abilities.' FROM games WHERE igdb_id = 281229 ON CONFLICT (game_id, language_code) DO NOTHING;
