INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DeepCover', 'In DeepCover, players solve a variety of fun and stimulating puzzles to outsmart evildoers, prevent scams, and save the day. Playing as an undercover agent, players are awarded more intel at every level they complete, used to outsmart scammers and help protect potential victims. Players are also able to customize their character, unlock new levels, play special training games, and learn additional info about real-life online scams and their impacts.' FROM games WHERE igdb_id = 317998 ON CONFLICT (game_id, language_code) DO NOTHING;
