INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iseran: Isekai Rantou', '最大４人でみんなでバトルパーティー！！！ 異世界乱闘、ちぢめて「いせらん」！！！ ありとあらゆる異世界から集いし者たちは、今日もバトる！！！ 様々な世界の者たちが迷い込んでくる謎の世界、「マザワルド」！ここでは、色んな競技で熱く激しいバトルが繰り広げられるのは日常茶飯事だ！ 勝利を目指せ！！！Let’s！いせらん！！！' FROM games WHERE igdb_id = 257675 ON CONFLICT (game_id, language_code) DO NOTHING;
