INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Hate You, Please Suffer', 'A woman becomes an adventurer and makes friends on a quest to pay rent - and maybe something much more. I Hate You, Please Suffer is an RPG set in a world where becoming an adventurer is a common career choice, where a woman tries to get by and find happiness regardless of how screwed up the world can be. Make money and find success in any way you can: from larger scale quests with loose continuity with each other and the surrounding world, to hunting down assorted weirdos for bounties, to catching fish.' FROM games WHERE igdb_id = 182051 ON CONFLICT (game_id, language_code) DO NOTHING;
