INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Citadel Unchained', 'A 90s inspired open world game. Featuring a rich story and lore. Dual wielding magic. A massive open world encouraging exploration! Numerous villages and settlements. Mountains, forests, lakes and even a sea! Ancient monuments and castles hidden amongst forgotten valleys. Desert Plains stretching as far as the eye can see. Enter a world of ancient feuds and uneasy alliances. Free to explore at your own leisure and you can set off in any direction.' FROM games WHERE igdb_id = 323571 ON CONFLICT (game_id, language_code) DO NOTHING;
