INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ryceam', 'Ryceam is a 3D track rhythm game. Aiming to offer unique game experience, we have developed brand new gameplay that combines the traditional drop-type gameplay, the innovative 3D visual effect and more flexible tracks to create graphs with distinct features. Besides, RYCEAM is a non-commercial game, which means that everyone can enjoy the full version of the game free of charge totally. And we insist on running this game without any profit thoroughly.' FROM games WHERE igdb_id = 262387 ON CONFLICT (game_id, language_code) DO NOTHING;
