INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bonfire and Tail', 'Bonfire and Tail is a multiplayer action party game developed by avidya studio. Through the gameplay, we want to bring players back to childhood and have simple fun together. Draw a torch from the bonfire and ignite other players'' tails! If your tail is on fire, wiggle it to put the fire out!' FROM games WHERE igdb_id = 250801 ON CONFLICT (game_id, language_code) DO NOTHING;
