INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('copper-jacket', 313466, '2023-08-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ocp.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Copper Jacket', 'Alert! Your former boss -- Commander Zaslavsky -- has kidnapped your wife-to-be in an attempt to make you do his dirty work. Your mission is to defeat this sinister commander and rescue the love of your life. Your best mate, Anatoly, has agreed to help you on your mission. You may really need his help as the journey will be rife with many challenges and obstacles to overcome. Zaslavsky has many men under his command as well as many war machines at his disposal. You must navigate through his defenses to reach his command center that rests atop a snowy mountain – it is here in which your beloved one is being held hostage. In addition to overseeing a powerful army, Zaslavsky is rather manipulative, so you should be cautious if he tries to communicate with you on your radio. Blast your way through 13 levels and 5 bosses in this brand-new, action-packed, 1-2 player NES game!' FROM games WHERE igdb_id = 313466 ON CONFLICT (game_id, language_code) DO NOTHING;
