INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Zelda: Link''s Initiation', 'In Link''s Initiation, brothers Sahasrahla & Aginah use their mystical abilities to project a dream into Link’s mind, in order to initiate him in the rites of the ancient Seven Sages. You must immerse yourself in Link''s unconscious, where everything has a double meaning, and analyze the hidden keys to focus his spirit and acquire the wisdom that will guide him on the Sages path. In this prequel to A Link to the Past, you will have to solve the puzzles to initiate Link into the mystical wisdom of the Seven Sages! Available for Windows, Mac and Linux in English and Spanish.' FROM games WHERE igdb_id = 330688 ON CONFLICT (game_id, language_code) DO NOTHING;
