INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Your Last Xmas', 'The house formerly belonged to a singer who had some success in the 1980s as part of a duo, singing about tropical holidays and whatnot, before going solo and achieving greater success with his newfound freedom. There were always the rumors however - that he may have been connected a series of gruesome cannibalistic murders. He passed away a few years back, but some say he returns every December 25th - and Last Christmas, he ate people''s hearts...' FROM games WHERE igdb_id = 280186 ON CONFLICT (game_id, language_code) DO NOTHING;
