INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Up', 'Join Alf in "Fantasy UP!" in a world upended by a gravity-reversing Demon King. As Alf, ascend, gain experiences, and aim to defeat the Demon King. This RPG tests determination, with average completion of 30-60 minutes. Every fall strengthens you. Ready to climb, Alf?' FROM games WHERE igdb_id = 259286 ON CONFLICT (game_id, language_code) DO NOTHING;
