INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ParryRobot', 'ParryRobot is a 3D action game where you play as a tiny but agile robot, “PAR 12-H”. Using the game’s “Parry System”, you are tasked with overcoming the mysterious, hulking “TB 001-L”…a massive automaton who’s set its eyes on your metallic hide!' FROM games WHERE igdb_id = 277371 ON CONFLICT (game_id, language_code) DO NOTHING;
