INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle by Nikoli W Hitori', '"Hitori" is a puzzle in which you fill in any unnecessary numbers, making sure that the same number doesn''t appear twice in the same line. Once you get the hang of it, you can feel the joy of figuring out the many various gimmicks thought up by the creator. This is a puzzle for real connoisseurs.' FROM games WHERE igdb_id = 256430 ON CONFLICT (game_id, language_code) DO NOTHING;
