INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Recommendation Dog!!', 'Recommendation Dog!! is an adorable action-puzzle game about being a tiny dog with a very big job. You work at a temp agency, cranking through names in your rotary organizer to fulfill the wacky, lovely, and strange requests of the people who come through your door. Connect the right people with the places that need them, make fast-paced choices, and get the high score you deserve! Good boy. This is Recommendation Dog - and you are a very good boy indeed.' FROM games WHERE igdb_id = 151983 ON CONFLICT (game_id, language_code) DO NOTHING;
