INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grezzodue 2', 'Grezzodue 2 is an audacious blend of FPS, immersive sim and satirical horror, steeped in a rich, provocative atmosphere. Featuring one of the most expansive open-worlds based on Perugia, Italy, it promises an epic, nonlinear story with multiple outcomes. With its unique combination of ultra-violence, Italian humor, and biting social commentary, Grezzodue 2 stands for audacity, controversy, and unforgettable gaming.' FROM games WHERE igdb_id = 255403 ON CONFLICT (game_id, language_code) DO NOTHING;
